// ── 다크 테마 안내 화면 전용 색상 ─────────────────────────────────────────────
private val NavBg           = Color(0xFF1C1C1E)   // 화면 배경
private val NavSurface      = Color(0xFF2C2C2E)   // 카드 배경
private val NavDivider      = Color(0xFF3A3A3C)   // 구분선
private val NavAmber        = Color(0xFFF2B705)   // 노란색 (남은 거리·시간, 위치 카드)
private val NavAmberOnCard  = Color(0xFF1C1C1E)   // 노란 카드 위 텍스트
private val NavExit         = Color(0xFFFF6B6B)   // X 버튼 (안내 종료)
private val NavTabInactive  = Color(0xFF636366)   // 비활성 탭 아이콘/레이블

// ─────────────────────────────────────────────────────────────────────────────

/**
 * 네비게이션 안내 화면.
 *
 * 고대비 다크 UI로 구성됩니다.
 *   - 상단: 남은 거리 / 남은 시간 지표
 *   - 중단: 현재 위치 카드 (노란 배경)
 *   - 하단: 안내 종료 카드
 *   - 최하단: 탭 바
 *
 * @param uiState   [NavigationUiState] — ViewModel 에서 수집한 상태
 * @param onAction  사용자 인터랙션을 ViewModel 로 전달하는 콜백
 */
@Composable
fun NavigationScreen(
    uiState: NavigationUiState,
    onAction: (NavigationUiAction) -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .background(NavBg),
    ) {
        // 상단 지표 행
        NavigationMetricsRow(
            distanceLabel = uiState.stepCard.metrics.getOrNull(0)?.value ?: "-",
            timeLabel = uiState.stepCard.metrics.getOrNull(1)?.value ?: "-",
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = EumSpacing.medium)
                .padding(top = EumSpacing.large),
        )

        Spacer(modifier = Modifier.height(EumSpacing.large))

        // 현재 위치 카드 (flex 1)
        NavigationLocationCard(
            locationLabel = uiState.mapOverlay.currentLocation?.label ?: "현재 위치",
            modifier = Modifier
                .fillMaxWidth()
                .weight(1f)
                .padding(horizontal = EumSpacing.medium),
        )

        Spacer(modifier = Modifier.height(EumSpacing.medium))

        // 저장 / 완료 액션 버튼
        NavigationActionButtons(
            enabled = uiState.isExitEnabled,
            onSaveClick = { onAction(NavigationUiAction.SaveBookmarkClicked) },
            onCompleteClick = { onAction(NavigationUiAction.NavigationCompleteClicked) },
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = EumSpacing.medium),
        )

        Spacer(modifier = Modifier.height(EumSpacing.medium))
    }
}

// ── 상단 지표 행 ──────────────────────────────────────────────────────────────

@Composable
private fun NavigationMetricsRow(
    distanceLabel: String,
    timeLabel: String,
    modifier: Modifier = Modifier,
) {
    Row(
        modifier = modifier,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // 남은 거리
        NavigationMetricItem(
            label = "남은 거리",
            value = distanceLabel,
            modifier = Modifier
                .weight(1f)
                .semantics(mergeDescendants = true) {
                    contentDescription = "남은 거리 $distanceLabel"
                },
        )

        // 구분선
        Box(
            modifier = Modifier
                .width(1.5.dp)
                .height(72.dp)
                .background(NavDivider),
        )

        // 남은 시간
        NavigationMetricItem(
            label = "남은 시간",
            value = timeLabel,
            modifier = Modifier
                .weight(1f)
                .semantics(mergeDescendants = true) {
                    contentDescription = "남은 시간 $timeLabel"
                },
        )
    }
}

@Composable
private fun NavigationMetricItem(
    label: String,
    value: String,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(EumSpacing.xSmall),
    ) {
        Text(
            text = label,
            style = MaterialTheme.typography.bodyMedium,
            color = NavTabInactive,
            textAlign = TextAlign.Center,
        )
        Text(
            text = value,
            fontSize = 56.sp,
            fontWeight = FontWeight.ExtraBold,
            color = NavAmber,
            textAlign = TextAlign.Center,
            letterSpacing = (-1).sp,
        )
    }
}

// ── 현재 위치 카드 ────────────────────────────────────────────────────────────

@Composable
private fun NavigationLocationCard(
    locationLabel: String,
    modifier: Modifier = Modifier,
) {
    Surface(
        modifier = modifier.semantics(mergeDescendants = true) {
            contentDescription = "현재 위치: $locationLabel"
        },
        shape = RoundedCornerShape(EumRadius.large),
        color = NavAmber,
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(EumSpacing.xLarge),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
        ) {
            Icon(
                painter = painterResource(id = R.drawable.ic_voice_location_pin),
                contentDescription = null,
                tint = NavAmberOnCard,
                modifier = Modifier.size(72.dp),
            )
            Spacer(modifier = Modifier.height(EumSpacing.medium))
            Text(
                text = locationLabel,
                fontSize = 32.sp,
                fontWeight = FontWeight.ExtraBold,
                color = NavAmberOnCard,
                textAlign = TextAlign.Center,
            )
        }
    }
}

// ── 저장 / 완료 액션 버튼 ─────────────────────────────────────────────────────

/**
 * 안내 종료 후 표시되는 두 개의 액션 버튼.
 *
 * @param enabled      버튼 활성 여부 (경로가 준비된 경우 true)
 * @param onSaveClick  "저장" 클릭 → 북마크 저장 후 저장 목록으로 이동
 * @param onCompleteClick "완료" 클릭 → 홈(지도) 화면으로 복귀
 */
@Composable
private fun NavigationActionButtons(
    enabled: Boolean,
    onSaveClick: () -> Unit,
    onCompleteClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val alpha = if (enabled) 1f else 0.4f

    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(EumSpacing.small),
    ) {
        // 저장 버튼
        val saveInteraction = remember { MutableInteractionSource() }
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(72.dp)
                .clip(RoundedCornerShape(EumRadius.large))
                .background(NavAmber.copy(alpha = alpha))
                .clickable(
                    enabled = enabled,
                    interactionSource = saveInteraction,
                    indication = rememberRipple(color = NavAmberOnCard),
                    onClick = onSaveClick,
                )
                .semantics {
                    role = Role.Button
                    contentDescription = if (enabled) "저장. 탭하여 경로를 북마크에 저장합니다." else "저장. 비활성 상태"
                },
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(
                painter = painterResource(id = R.drawable.ic_action_favorite),
                contentDescription = null,
                tint = NavAmberOnCard,
                modifier = Modifier.size(28.dp),
            )
            Spacer(modifier = Modifier.width(EumSpacing.small))
            Text(
                text = "저장",
                fontSize = 26.sp,
                fontWeight = FontWeight.ExtraBold,
                color = NavAmberOnCard,
            )
        }

        // 완료 버튼
        val completeInteraction = remember { MutableInteractionSource() }
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(72.dp)
                .clip(RoundedCornerShape(EumRadius.large))
                .background(NavSurface.copy(alpha = alpha))
                .clickable(
                    enabled = enabled,
                    interactionSource = completeInteraction,
                    indication = rememberRipple(color = NavExit),
                    onClick = onCompleteClick,
                )
                .semantics {
                    role = Role.Button
                    contentDescription = if (enabled) "완료. 탭하여 안내를 종료하고 홈으로 돌아갑니다." else "완료. 비활성 상태"
                },
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Icon(
                painter = painterResource(id = R.drawable.ic_action_close),
                contentDescription = null,
                tint = Color.White.copy(alpha = alpha),
                modifier = Modifier.size(28.dp),
            )
            Spacer(modifier = Modifier.width(EumSpacing.small))
            Text(
                text = "완료",
                fontSize = 26.sp,
                fontWeight = FontWeight.ExtraBold,
                color = Color.White.copy(alpha = alpha),
            )
        }
    }
}

